function fetchWorkflowRunJobs(scm, owner, repo, runId) {
    return (scm && typeof scm.getWorkflowRunJobs === 'function')
        ? scm.getWorkflowRunJobs(runId)
        : github_get_workflow_run_jobs({
            workspace: owner, repository: repo, runId: runId
