                    { id: 8, name: 'gate', conclusion: 'success' },
                    { name: 'noid', conclusion: 'failure' }
                ] };
            },
            getJobLogs: function (id) { return 'ERR' + id; }
        };
        var out = gh.fetchGithubRunLogs({ details_url: 'https://x/actions/runs/99' }, scm, 'o', 'r');
