function buildCiFailuresHeader(failedChecks, headSha, hasFullLog) {
   var md = '# ⚠️ Failed CI Checks — Fix Before Completing Rework\n';
   if (hasFullLog !== false) {
       md += 'Full (untruncated) logs are available in `ci_failures_full.log`.\n';
   } else {
       md += '⚠️ Full logs could NOT be saved (`ci_failures_full.log` write failed) — use each check\'s **Details** link below.\n';
   }
   md += failedChecks.length + ' check(s) failed on commit `' + headSha.substring(0, 8) + '`:\n';
   return md;
}

function buildCiFailuresResolutionSection(hasFullLog) {
   var section = '---\n## Resolution\n' +
       '1. Read the error log(s) above to identify the root cause\n';
   if (hasFullLog !== false) {
       section += '2. For more context, open `ci_failures_full.log` with the complete logs\n';
   } else {
       section += '2. For more context, open the failing check(s) via their **Details** links above (full-log write failed)\n';
   }
   section += '3. Fix the underlying code issue(s)\n' +
       '4. CI will re-run automatically after the push — all checks must pass\n';
   return section;
}
