    if (!logs) return null;
    var lines = logs.split('\n');
    var snippet = lines.slice(-500).join('\n');
    return {
        md: '**' + label + ' (last 500 lines)**:\n\n```\n' + snippet + '\n```\n\n',
        full: '=== ' + label + ' for: ' + check.name + ' ===\n' +
