```js
/** gh-1045: extract a BARE check-run id (github.com/o/runs/{id}) — null for /actions/runs/ URLs. */
function extractGithubCheckRunId(check) {
   var url = (check && check.details_url) ? String(check.details_url) : '';
   if (!url) return null;
   if (/\/actions\/runs\/\d+/.test(url)) return null; // workflow-run URL — the run path owns it
   var m = url.match(/\/runs\/(\d+)/);
   return m ? m[1] : null;
}
